import hashlib
import hmac
import json
from collections import OrderedDict


def _parse_request(raw, max_body=1_000_000):
    end = raw.find(b"\r\n\r\n")
    if end < 0:
        raise ValueError("incomplete head")
    lines = raw[:end].decode("latin-1").split("\r\n")
    parts = lines[0].split(" ")
    if len(parts) != 3 or not all(parts) or not parts[2].startswith("HTTP/1."):
        raise ValueError("bad request line")
    headers = {}
    for line in lines[1:]:
        name, colon, value = line.partition(":")
        if not colon or not name or " " in name or "\t" in name:
            raise ValueError("bad header")
        name, value = name.lower(), value.strip()
        headers[name] = headers[name] + ", " + value if name in headers else value
    body = b""
    if "content-length" in headers:
        text = headers["content-length"]
        if not text.isdigit() or int(text) > max_body:
            raise ValueError("bad content-length")
        body = raw[end + 4:end + 4 + int(text)]
        if len(body) < int(text):
            raise ValueError("incomplete body")
    return parts[0], parts[1], headers, body


def _verified(header, body, secrets, now, tolerance):
    if not header:
        return False
    stamps, signatures = [], []
    for item in header.split(","):
        name, eq, value = item.strip().partition("=")
        if eq and name == "t":
            stamps.append(value)
        elif eq and name == "v1":
            signatures.append(value)
    if len(stamps) != 1 or not stamps[0].isdigit() or not signatures:
        return False
    timestamp = int(stamps[0])
    if abs(now - timestamp) > tolerance:
        return False
    for secret in secrets:
        expected = hmac.new(secret, f"{timestamp}.".encode("ascii") + body, hashlib.sha256).hexdigest()
        if any(hmac.compare_digest(expected, s) for s in signatures):
            return True
    return False


class WebhookReceiver:
    def __init__(self, secrets, clock, path="/webhooks", tolerance=300, memory=1000):
        self.secrets = list(secrets)
        self.clock = clock
        self.path = path
        self.tolerance = tolerance
        self.memory = memory
        self.handlers = {}
        self.ignored = []
        self._ids = OrderedDict()
        self._versions = {}

    def on(self, event_type, handler):
        self.handlers[event_type] = handler

    def _remember(self, event_id):
        self._ids[event_id] = True
        while len(self._ids) > self.memory:
            self._ids.popitem(last=False)

    def receive(self, raw):
        try:
            method, target, headers, body = _parse_request(raw)
        except ValueError:
            return 400
        if target.split("?", 1)[0] != self.path:
            return 404
        if method != "POST":
            return 405
        if not _verified(headers.get("webhook-signature"), body, self.secrets, self.clock(), self.tolerance):
            return 401
        try:
            event = json.loads(body)
        except (ValueError, UnicodeDecodeError):
            return 400
        if not isinstance(event, dict):
            return 400
        if not all(isinstance(event.get(k), str) for k in ("id", "type", "object_id")):
            return 400
        version = event.get("version")
        if not isinstance(version, int) or isinstance(version, bool):
            return 400

        if event["id"] in self._ids:
            return 200
        applied = self._versions.get(event["object_id"])
        if applied is not None and version <= applied:
            self._remember(event["id"])
            return 200
        handler = self.handlers.get(event["type"])
        if handler is None:
            self.ignored.append(event["id"])
            self._remember(event["id"])
            return 200
        try:
            handler(event)
        except Exception:
            return 500
        self._versions[event["object_id"]] = version
        self._remember(event["id"])
        return 200
